const SUBJECT_DIR = path.join(ROOT, "prep/overlays/maikbook2/medicine");
const KB_DIR = path.join(ROOT, "kb/reference");
const LESSON_DIR = path.join(ROOT, "prep/lessons/v1");
const MODEL = "muse-wonder (local authoring, no external API)";
const ITEM_META = { prov: "SMD", gen: "hand", set: "maikbook2", d: 1, cog: "recall", credit: "StewardMD original medical knowledge base", licence: "CC BY 4.0 (StewardMD original)", licenceStandard: "CC BY 4.0", licenseUrl: "https://creativecommons.org/licenses/by/4.0", quality: { status: "automated_checks_passed", gates: { author_self_check: { note: "Author-verified against standard peer references" } } } };
fs.mkdirSync(SUBJECT_DIR, { recursive: true });
const seenIds = new Set();
let failures = 0, written = 0, kbWritten = 0, kbSkipped = 0;
for (const m of M) {
  const steps = m.steps.map((s) => JSON.parse(JSON.stringify(s)));
  for (const s of steps) {
    const words = s.tx.split(/\s+/).filter(Boolean).length;
    if (words < 40 || words > 90) { console.error("FAIL", m.id, words); failures++; }
    if (s.say === s.tx) { console.error("SAYEQ", m.id); failures++; }
  }
  for (const q of m.mcqs) {
    if (seenIds.has(q.id)) { console.error("DUPID", q.id); failures++; }
    seenIds.add(q.id);
    if (!(q.q && q.q.length > 20 && q.o.length === 4 && q.a >= 0 && q.a < 4 && q.exp && q.exp.length > 20 && q.r.length === 4 && q.kp && q.kp.length > 5)) { console.error("MCQSHAPE", m.id, q.id); failures++; }
  }
  const quiz = m.mcqs.map((q) => q.id);
  const lesson = {
    v: 1, module: m.id, subject: "medicine", title: m.title, minutes: 6,
    steps, quiz, src: [], refs: [REF], gen: "AI", run: "books2-lon5", model: MODEL,
    checks: { shape: true, numbers: true, drugs: true, verbatim: true, dashes: true, verify: true, redone: 0, dropped: 0, kbWords: 0, itemN: m.mcqs.length },
  };
  const probs = LP.checkLesson(lesson);
  if (probs.length) { console.error("LESSON FAIL", m.id, JSON.stringify(probs)); failures++; continue; }
  fs.writeFileSync(path.join(LESSON_DIR, m.id + ".json"), JSON.stringify(lesson, null, 2) + "\n");
  written++;
  const kbPath = path.join(KB_DIR, m.kb + ".json");
  if (!fs.existsSync(kbPath)) {
    fs.writeFileSync(kbPath, JSON.stringify({ id: m.kb, name: m.kbName, aliases: [...m.aliases], class: "non_infective", system: "Medicine", specialty: "Endocrinology", referenceOnly: true, review: { status: "ai_drafted" }, reference: { source: REF, sourceEdition: "topic map (2026-10-14)", pages: null, clinicalPearls: [...m.pearls], pathophysiology: m.patho, additionalDifferentials: [...m.diffs], additionalInvestigations: [...m.invs] } }, null, 2) + "\n");
    kbWritten++;
  } else kbSkipped++;
  const items = m.mcqs.map((q, i) => {
    const rot = (arr, k) => arr.map((_, j) => arr[(j + k) % arr.length]);
    const r = (i + M.indexOf(m)) % 4;
    return { ...ITEM_META, ...q, o: rot(q.o, r), r: rot(q.r, r), a: (q.a - r + 4) % 4, topic: m.id };
  });
  fs.writeFileSync(path.join(SUBJECT_DIR, m.id + ".json"), JSON.stringify({ topic: m.id, set: "maikbook2", v: 1, items }, null, 2) + "\n");
}
let idx = JSON.parse(fs.readFileSync(path.join(LESSON_DIR, "index.json"), "utf8"));
for (const m of M) idx.modules[m.id] = { title: m.title, minutes: 6, steps: m.steps.length, gen: "AI" };
fs.writeFileSync(path.join(LESSON_DIR, "index.json"), JSON.stringify(idx, null, 1) + "\n");
let counts = JSON.parse(fs.readFileSync(path.join(ROOT, "prep/bank/overlay-counts.json"), "utf8"));
counts.sets.maikbook2 = counts.sets.maikbook2 || {};
counts.sets.maikbook2["medicine"] = counts.sets.maikbook2["medicine"] || {};
for (const m of M) counts.sets.maikbook2["medicine"][m.id] = m.mcqs.length;
fs.writeFileSync(path.join(ROOT, "prep/bank/overlay-counts.json"), JSON.stringify(counts, null, 1) + "\n");
let tc = fs.readFileSync(path.join(ROOT, "test/prep-books-mcqs.test.mjs"), "utf8");
if (!tc.includes('"medicine"')) tc = tc.replace('["obstetrics-gynaecology", "pathology", "pharmacology", "ent", "psychiatry", "ophthalmology", "microbiology"]', '["obstetrics-gynaecology", "pathology", "pharmacology", "ent", "psychiatry", "ophthalmology", "microbiology", "medicine"]');
if (!tc.includes("90 medicine")) {
  tc = tc.replace(/(assert\.equal\(totalItems, )(\d+)(, "Expected \d+ high-yield verified MCQs in maikbook2)/, (m0, pre, n, post) => `${pre}${Number(n) + 90}${post}`);
  tc = tc.replace("220 microbiology)\"", "220 microbiology + 90 medicine)\"");
}
fs.writeFileSync(path.join(ROOT, "test/prep-books-mcqs.test.mjs"), tc);
let qfail = 0;
for (const m of M) {
  const ov = JSON.parse(fs.readFileSync(path.join(SUBJECT_DIR, m.id + ".json"), "utf8"));
  const oids = ov.items.map((x) => x.id).sort().join(",");
  const qids = [...m.mcqs.map((q) => q.id)].sort().join(",");
  if (oids !== qids) { console.error("QUIZMISMATCH", m.id); qfail++; }
}
console.log("modules:", M.length, "mcqs:", M.reduce((n, m) => n + m.mcqs.length, 0), "kbWritten:", kbWritten, "kbSkipped:", kbSkipped, "lesson failures:", failures, "quiz mismatch:", qfail);
if (failures || qfail) process.exit(1);

